import React, { useState } from 'react';

function useFeatureFlag() {
  const [isEnabled, setIsEnabled] = useState(false);
  const toggleFlag = () => setIsEnabled(prev => !prev);
  return { isEnabled, toggleFlag };
}

function App() {
  const { isEnabled, toggleFlag } = useFeatureFlag();
  return (
    <div>
      <h1>Feature Flag Demo</h1>
      {isEnabled ? (
        <p>Feature is enabled</p>
      ) : (
        <p>Feature is disabled</p>
      )}
      <button onClick={toggleFlag}>Toggle Feature</button>
    </div>
  );
}

export default App;
